29	function buildEnv(env, defaultFile) {
30	  const merged = { ...process.env, PORT: '0', DATA_FILE: defaultFile, ...env };
31	  for (const key of Object.keys(merged)) if (merged[key] === undefined) delete merged[key];
32	  return merged;
33	}
