35	function spawnServer({ env = {}, cwd, script = SERVER }) {
36	  const defaultFile = path.join(mkTmp(), 'bookings.json');
37	  const child = spawn(process.execPath, [script], {
38	    env: buildEnv(env, defaultFile),
39	    cwd: cwd ?? ROOT,
40	    stdio: ['ignore', 'pipe', 'pipe'],
41	  });
42	  const out = { stdout: '', stderr: '' };
43	  child.stdout.setEncoding('utf8').on('data', (d) => { out.stdout += d; });
44	  child.stderr.setEncoding('utf8').on('data', (d) => { out.stderr += d; });
45	  const exited = new Promise((resolve) => {
46	    child.once('exit', (code) => resolve(code));
47	  });
48	  return { child, out, exited, defaultFile };
49	}
50	
51	export function start({ env = {}, cwd, script } = {}) {
52	  const { child, out, exited, defaultFile } = spawnServer({ env, cwd, script });
53	  const server = {
54	    child,
55	    file: env.DATA_FILE ?? defaultFile,
56	    stdout: () => out.stdout,
57	    stderr: () => out.stderr,
58	    stop: async () => {
59	      liveServers.delete(server);
60	      child.kill('SIGKILL');
61	      await exited;
62	    },
63	  };
64	  liveServers.add(server);
65	  return new Promise((resolve, reject) => {
66	    const timer = setTimeout(() => reject(new Error('server did not start in time')), 5000);
67	    const check = () => {
68	      const m = LISTEN_LINE.exec(out.stdout);
69	      if (m) {
70	        clearTimeout(timer);
71	        resolve({ ...server, port: Number(m[1]) });
72	      }
73	    };
74	    child.stdout.on('data', check);
75	    exited.then((code) => {
76	      clearTimeout(timer);
77	      reject(new Error(`server exited early (${code}): ${out.stderr}`));
78	    });
79	  });
80	}
