82	export async function runToExit({ env = {}, cwd } = {}) {
83	  const { child, out, exited } = spawnServer({ env, cwd });
84	  const timer = setTimeout(() => child.kill('SIGKILL'), 5000);
85	  const code = await exited;
86	  clearTimeout(timer);
87	  return { code, stdout: out.stdout, stderr: out.stderr };
88	}
