90	export function request(port, { method = 'GET', path: reqPath, headers = {}, body } = {}) {
91	  return new Promise((resolve, reject) => {
92	    const payload = body === undefined ? undefined : Buffer.from(body);
93	    const finalHeaders = { ...headers };
94	    if (payload) finalHeaders['content-length'] = payload.length;
95	    const req = http.request(
96	      { host: '127.0.0.1', port, method, path: reqPath, headers: finalHeaders, agent: false },
97	      (res) => {
98	        const chunks = [];
99	        res.on('data', (c) => chunks.push(c));
100	        res.on('end', () => {
101	          const text = Buffer.concat(chunks).toString('utf8');
102	          let json;
103	          try { json = JSON.parse(text); } catch { json = undefined; }
104	          resolve({ status: res.statusCode, headers: res.headers, text, json });
105	        });
106	      },
107	    );
108	    req.on('error', reject);
109	    req.end(payload);
110	  });
111	}
