113	export function rawRequest(port, text) {
114	  return new Promise((resolve, reject) => {
115	    const chunks = [];
116	    const socket = net.connect(port, '127.0.0.1', () => socket.write(text));
117	    socket.on('data', (c) => chunks.push(c));
118	    socket.on('end', () => resolve(Buffer.concat(chunks).toString('utf8')));
119	    socket.on('error', reject);
120	  });
121	}
