127	export function parseRaw(text) {
128	  const [head, ...rest] = text.split('\r\n\r\n');
129	  return { status: Number(/^HTTP\/1\.1 (\d+)/.exec(head)[1]), head, body: rest.join('\r\n\r\n') };
130	}
