135	export function post(port, value, headers = {}) {
136	  const body = typeof value === 'string' || Buffer.isBuffer(value) ? value : JSON.stringify(value);
137	  return request(port, {
138	    method: 'POST',
139	    path: '/api/bookings',
140	    headers: { 'content-type': 'application/json', ...headers },
141	    body,
142	  });
143	}
