151	let dayCounter = 0;
152	export function uniqueDate() {
153	  const n = dayCounter++;
154	  const year = 2040 + Math.floor(n / 336);
155	  const month = String(1 + (Math.floor(n / 28) % 12)).padStart(2, '0');
156	  const day = String(1 + (n % 28)).padStart(2, '0');
157	  return `${year}-${month}-${day}`;
158	}
